   "motivo": "Explica 'cromatografia', que não estava definida."
  },
  {
   "campo": "resolucao.armadilha",
   "depois": "Cair em alternativas com 'todos', 'apenas' ou 'extremamente lentos', que distorcem o texto, em vez de ligar 'vida curta' a 'espécie instável'.",
   "motivo": "Ajuste de redação."
  }
 ],
